questionvariables.text:
/*
Shared Curriculum-Independent
Question Bank

Linear Relations
QLIN-05

Two different straight-line relations
are generated.

Slopes are small integers so that the
graph remains readable on the
[-6,6] Cartesian board.
*/


m1:rand_with_prohib(
    -2,
    2,
    [0]
);


m2:rand_with_prohib(
    -2,
    2,
    [0,m1]
);


c1:rand(5)-2;


/*
Choose c2 different from c1 so the
two lines have both different slopes
and different y-intercepts.
*/

c2:rand_with_prohib(
    -2,
    2,
    [c1]
);


/*
Target equations.
*/

equation1:y=m1*x+c1;
equation2:y=m2*x+c2;


/*
Convenient teacher/model points.
*/

ta1:[0,c1];
ta2:[1,m1+c1];

tb1:[0,c2];
tb2:[1,m2+c2];


/*
Initial draggable-point locations.

These are only starting positions.
They do not define the answer.
*/

start_ax1:-5;
start_ay1:5;

start_ax2:-4;
start_ay2:4;

start_bx1:4;
start_by1:4;

start_bx2:5;
start_by2:5;

feedbackvariables.text:
/* Distance between the two A points. A single duplicated point must not define a line. */
distA: (ans1[1]-ans2[1])^2 + (ans1[2]-ans2[2])^2;
/* Residuals against Relation A. Both draggable points must lie on the required line. */
resA1: ans1[2] - (m1*ans1[1]+c1);
resA2: ans2[2] - (m1*ans2[1]+c1);
errorA: resA1^2 + resA2^2;
/* Swapped-line diagnostic: A points were placed on Relation B. */
swapA1: ans1[2] - (m2*ans1[1]+c2);
swapA2: ans2[2] - (m2*ans2[1]+c2);
swapErrorA: swapA1^2 + swapA2^2;

/* Distance between the two B points. */
distB: (ans3[1]-ans4[1])^2 + (ans3[2]-ans4[2])^2;
/* Residuals against Relation B. */
resB1: ans3[2] - (m2*ans3[1]+c2);
resB2: ans4[2] - (m2*ans4[1]+c2);
errorB: resB1^2 + resB2^2;
/* Swapped-line diagnostic. */
swapB1: ans3[2] - (m1*ans3[1]+c1);
swapB2: ans4[2] - (m1*ans4[1]+c1);
swapErrorB: swapB1^2 + swapB2^2;
